  293: // readRawTranscript streams one session's stored transcript bytes.
  294: func (r *apiCheckpointReader) readRawTranscript(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) ([]byte, error) {
  295: 	path := fmt.Sprintf("/api/v1/repos/%s/checkpoints/%s/transcript/raw?%s",
  296: 		url.PathEscape(r.repoID), url.PathEscape(checkpointID.String()),
  297: 		url.Values{"session": []string{strconv.Itoa(sessionIndex)}}.Encode())
  298: 
  299: 	resp, err := r.client.GetStream(ctx, path, nil)
  300: 	if err != nil {
  301: 		return nil, fmt.Errorf("read transcript for checkpoint %s from %s: %w", checkpointID, r.ownerRepo, err)
  302: 	}
  303: 	defer resp.Body.Close()
  304: 
  305: 	if err := api.CheckResponse(resp); err != nil {
  306: 		// A missing transcript blob is a real, reportable state (the
  307: 		// checkpoint exists but its bytes were never stored or have been
  308: 		// pruned) — distinct from the checkpoint itself being absent, which
  309: 		// Read already reported.
  310: 		if api.IsHTTPErrorStatus(err, http.StatusNotFound) {
  311: 			return nil, fmt.Errorf("checkpoint %s in %s has no stored transcript", checkpointID, r.ownerRepo)
  312: 		}
  313: 		return nil, fmt.Errorf("read transcript for checkpoint %s from %s: %w", checkpointID, r.ownerRepo, err)
  314: 	}
  315: 
  316: 	// LimitReader+1 so a transcript exactly at the cap is not mistaken for an
  317: 	// oversized one, and an oversized one is an error rather than a silent
  318: 	// truncation into the renderer.
  319: 	body, err := io.ReadAll(io.LimitReader(resp.Body, maxAPITranscriptBytes+1))
  320: 	if err != nil {
  321: 		return nil, fmt.Errorf("read transcript for checkpoint %s from %s: %w", checkpointID, r.ownerRepo, err)
  322: 	}
  323: 	if len(body) > maxAPITranscriptBytes {
  324: 		return nil, fmt.Errorf("transcript for checkpoint %s in %s exceeds the %d MB read limit", checkpointID, r.ownerRepo, maxAPITranscriptBytes>>20)
  325: 	}
  326: 	return body, nil
  327: }
