+func newShiftVerifyCmd() *cobra.Command {
+	var contractPath string
+	var outputDir string
+	var invariantFlags []string
+	var requirementFlag string
+	var structuralFlag string
+	var testFlag string
+
+	cmd := &cobra.Command{
+		Use:   "verify",
